function isConfigStale(e){return!!(e&&(e.message||'').includes('Config changed'))}
function homeConfigPatch(){const p={};let n=0;if(homeSwitchPending.homeBrewByWeight){p.brewByWeight=$('homeBrewByWeight').checked;n++}if(homeSwitchPending.homeAvoidBbwShotWithoutScale){p.avoidBbwShotWithoutScale=$('homeAvoidBbwShotWithoutScale').checked;n++}if(homeSwitchPending.homeSoundAlertsEnabled){p.soundAlertsEnabled=$('homeSoundAlertsEnabled').checked;n++}return n?withBaseRev(p):null}
async function flushHomeGuards(){if(homeFlushBusy){scheduleHomeGuardFlush();return}homeFlushBusy=true;updateHomeGuardSwitchesLock();const doConfig=homeFlushConfig,doPreset=homeFlushPreset;homeFlushConfig=false;homeFlushPreset=false;try{if(doConfig){for(let i=0;i<2;i++){const patch=homeConfigPatch();if(!patch)break;try{await command('/api/v1/config',patch,1);syncSettingsFromHomeSwitches();break}catch(e){await refreshStatus();if(i||!isConfigStale(e)){message(e&&e.message?e.message:'Request failed.','error');clearHomePend();await refreshStatus();return}}}}if(doPreset){try{await ensureSettingsHydrated()}catch(e){message(e&&e.message?e.message:'Request failed.','error');clearHomePend();await refreshStatus();return}syncSettingsFromHomeSwitches();if((await saveBrewPreset())===false){clearHomePend();await refreshStatus()}}}finally{homeFlushBusy=false;updateHomeGuardSwitchesLock();if(homeFlushConfig||homeFlushPreset)scheduleHomeGuardFlush()}}
function recipeBrewByWeight(){const active=presetState.items.find(x=>x.id===presetState.activeId);return active?!!active.brewByWeight:true}
