async function saveMachineConfig(){try{await ensureSettingsHydrated()}catch(e){message(e.message,'error');return}const err=validateMachineClient();if(err){showFieldError(err.id,err.msg);return}clearFieldErrors();try{await command('/api/v1/config',withBaseRev(machinePayload()),1);configDirty=false;if($('configDirtyHint'))$('configDirtyHint').classList.add('hidden')}catch(e){message(e&&e.message?e.message:'Request failed.','error');await refreshStatus()}}
