function commitRenamePreset(p,name){const t=(name||'').trim();if(!t){message('Name is required.','error');return}if(presetState.items.some(x=>x.id!==p.id&&x.name===t)){message('Name already in use.','error');return}command('/api/v1/presets',{action:'rename',id:p.id,name:t})}
